-- Replace the generated weather question stems with topic-specific quiz items.
-- Existing quizzes are left untouched; these catalog versions seed as drafts
-- so they follow the normal independent review and publication workflow.
UPDATE starter_content_catalog AS c
SET quiz_en=v.quiz_en,
    quiz_fil=v.quiz_fil,
    explanation_en=v.explanation_en,
    explanation_fil=v.explanation_fil,
    options=v.options::jsonb
FROM (VALUES
 ($$starter-weather-pressure$$,
  $$A weather station records air pressure. What does air pressure measure?$$,
  $$Ano ang sinusukat ng presyon ng hangin?$$,
  $$Air pressure is the force from the weight of air above a surface.$$ ,
  $$Ang presyon ng hangin ay puwersang dulot ng bigat ng hanging nasa ibabaw ng isang lugar.$$ ,
  $$[{"en":"The force from air above a surface","fil":"Puwersa mula sa hanging nasa ibabaw ng isang lugar","correct":true},{"en":"The amount of water vapor in air","fil":"Dami ng singaw ng tubig sa hangin","correct":false},{"en":"How fast air is moving","fil":"Bilis ng paggalaw ng hangin","correct":false},{"en":"How warm the ground is","fil":"Init ng lupa","correct":false}]$$),
 ($$starter-weather-climate$$,
  $$A town compares its usual rainy and dry seasons over many years. What is it describing?$$,
  $$Inihahambing ng isang bayan ang karaniwang tag-ulan at tag-init nito sa loob ng maraming taon. Ano ang inilalarawan nito?$$,
  $$Climate describes long-term weather patterns in a region, unlike a report about one day.$$ ,
  $$Inilalarawan ng klima ang pangmatagalang padron ng panahon sa isang rehiyon, hindi lamang ang lagay sa isang araw.$$ ,
  $$[{"en":"The region’s climate","fil":"Klima ng rehiyon","correct":true},{"en":"Today’s weather only","fil":"Lagay ng panahon ngayong araw lamang","correct":false},{"en":"Air pressure at one station","fil":"Presyon ng hangin sa isang estasyon","correct":false},{"en":"A single storm","fil":"Isang bagyo lamang","correct":false}]$$),
 ($$starter-weather-cloud-droplets$$,
  $$What makes clouds visible in the sky?$$,
  $$Ano ang dahilan kung bakit nakikita ang mga ulap sa kalangitan?$$,
  $$Clouds are visible collections of tiny liquid water droplets, ice crystals, or both.$$ ,
  $$Nakikitang kumpol ng maliliit na patak ng tubig, kristal ng yelo, o pareho ang mga ulap.$$ ,
  $$[{"en":"Tiny water droplets, ice crystals, or both","fil":"Maliliit na patak ng tubig, kristal ng yelo, o pareho","correct":true},{"en":"Water vapor alone","fil":"Singaw ng tubig lamang","correct":false},{"en":"Smoke from fires","fil":"Usok mula sa apoy","correct":false},{"en":"Dust floating in space","fil":"Alikabok na lumulutang sa kalawakan","correct":false}]$$),
 ($$starter-weather-dewpoint$$,
  $$Air cools until it reaches the dew point. What can happen next?$$,
  $$Lumalamig ang hangin hanggang maabot nito ang dew point. Ano ang maaaring sumunod?$$,
  $$At the dew point, water vapor can begin condensing into liquid water.$$ ,
  $$Sa dew point, maaaring magsimulang mag-condense ang singaw ng tubig at maging likido.$$ ,
  $$[{"en":"Water vapor begins condensing into liquid","fil":"Nagsisimulang maging likido ang singaw ng tubig","correct":true},{"en":"Liquid water instantly boils","fil":"Agad kumukulo ang likidong tubig","correct":false},{"en":"Air stops moving","fil":"Humihinto ang paggalaw ng hangin","correct":false},{"en":"Ice turns directly into warm air","fil":"Direktang nagiging mainit na hangin ang yelo","correct":false}]$$),
 ($$starter-weather-fog$$,
  $$A low cloud forms close to the ground and reduces visibility. What is it called?$$,
  $$May mababang ulap na nabuo malapit sa lupa at nagpapalabo ng tanaw. Ano ang tawag dito?$$,
  $$Fog is a cloud of tiny water droplets that forms near the ground.$$ ,
  $$Ang hamog ay ulap ng maliliit na patak ng tubig na nabubuo malapit sa lupa.$$ ,
  $$[{"en":"Fog","fil":"Hamog","correct":true},{"en":"Hail","fil":"Yelo mula sa pagkulog at pagkidlat","correct":false},{"en":"A rainbow","fil":"Bahaghari","correct":false},{"en":"A high cirrus cloud","fil":"Mataas na cirrus cloud","correct":false}]$$),
 ($$starter-weather-cloud-gray$$,
  $$Why can a thick cloud look gray compared with a thin cloud?$$,
  $$Bakit maaaring magmukhang kulay-abo ang makapal na ulap kumpara sa manipis na ulap?$$,
  $$A thick cloud lets less sunlight pass through, so it can appear gray.$$ ,
  $$Mas kaunting sikat ng araw ang nakalulusot sa makapal na ulap kaya maaari itong magmukhang kulay-abo.$$ ,
  $$[{"en":"Less sunlight passes through it","fil":"Mas kaunting sikat ng araw ang nakalulusot dito","correct":true},{"en":"It is made entirely of smoke","fil":"Puro usok ang bumubuo rito","correct":false},{"en":"It is farther from the ground","fil":"Mas malayo ito sa lupa","correct":false},{"en":"It contains no water or ice","fil":"Wala itong lamang tubig o yelo","correct":false}]$$),
 ($$starter-weather-hail$$,
  $$Which description identifies hail rather than ordinary rain?$$,
  $$Aling paglalarawan ang tumutukoy sa hail at hindi sa karaniwang ulan?$$,
  $$Hail is made of balls or lumps of ice that grow inside some thunderstorms.$$ ,
  $$Binubuo ang hail ng mga tipak o bola ng yelong lumalaki sa loob ng ilang thunderstorm.$$ ,
  $$[{"en":"Balls or lumps of ice from a thunderstorm","fil":"Mga bola o tipak ng yelo mula sa thunderstorm","correct":true},{"en":"Liquid drops that fall from layered clouds","fil":"Mga patak ng likidong bumabagsak mula sa mga ulap","correct":false},{"en":"Ice crystals that fall gently from cold clouds","fil":"Mga kristal ng yelong marahang bumabagsak mula sa malamig na ulap","correct":false},{"en":"A cloud that forms at ground level","fil":"Ulap na nabubuo sa mismong ibabaw ng lupa","correct":false}]$$),
 ($$starter-weather-humidity$$,
  $$A forecast says the air is very humid. Which quantity is high?$$,
  $$Sinasabi ng ulat-panahon na mataas ang humidity. Aling dami ang mataas?$$,
  $$Humidity describes how much water vapor is in the air.$$ ,
  $$Inilalarawan ng humidity kung gaano karaming singaw ng tubig ang nasa hangin.$$ ,
  $$[{"en":"Water vapor in the air","fil":"Singaw ng tubig sa hangin","correct":true},{"en":"Ice in the soil","fil":"Yelo sa lupa","correct":false},{"en":"The speed of sunlight","fil":"Bilis ng sikat ng araw","correct":false},{"en":"The weight of clouds","fil":"Bigat ng mga ulap","correct":false}]$$),
 ($$starter-weather-lightning$$,
  $$During a thunderstorm, a bright electrical discharge flashes across the sky. What is it?$$,
  $$Sa panahon ng thunderstorm, kumikislap sa kalangitan ang isang maliwanag na discharge ng kuryente. Ano ito?$$,
  $$Lightning is an electrical discharge in the atmosphere, often during thunderstorms.$$ ,
  $$Ang kidlat ay discharge ng kuryente sa atmospera na madalas mangyari kasabay ng thunderstorm.$$ ,
  $$[{"en":"Lightning","fil":"Kidlat","correct":true},{"en":"A rainbow","fil":"Bahaghari","correct":false},{"en":"Air pressure","fil":"Presyon ng hangin","correct":false},{"en":"Fog","fil":"Hamog","correct":false}]$$),
 ($$starter-weather-rain$$,
  $$What happens when water droplets in a cloud grow large and heavy enough?$$,
  $$Ano ang nangyayari kapag lumaki at bumigat nang sapat ang mga patak ng tubig sa ulap?$$,
  $$Large, heavy cloud droplets fall as rain.$$ ,
  $$Bumabagsak bilang ulan ang malalaki at mabibigat na patak mula sa ulap.$$ ,
  $$[{"en":"They fall to the ground as rain","fil":"Bumabagsak ang mga ito bilang ulan","correct":true},{"en":"They turn into invisible water vapor without falling","fil":"Nagiging di-nakikitang singaw ang mga ito nang hindi bumabagsak","correct":false},{"en":"They become air pressure","fil":"Nagiging presyon ng hangin ang mga ito","correct":false},{"en":"They move upward and become sunlight","fil":"Umaakyat ang mga ito at nagiging sikat ng araw","correct":false}]$$),
 ($$starter-weather-rainbow$$,
  $$Sunlight shines through raindrops. Which light processes can produce a rainbow?$$,
  $$Sumisinag ang araw sa mga patak ng ulan. Aling mga proseso ng liwanag ang maaaring lumikha ng bahaghari?$$,
  $$A rainbow can form when sunlight is refracted and reflected inside water droplets.$$ ,
  $$Maaaring mabuo ang bahaghari kapag na-refract at na-reflect ang sikat ng araw sa loob ng mga patak ng tubig.$$ ,
  $$[{"en":"Refraction and reflection inside droplets","fil":"Refraction at reflection sa loob ng mga patak","correct":true},{"en":"Evaporation and freezing in the air","fil":"Pagsingaw at pagyeyelo sa hangin","correct":false},{"en":"Absorption of all sunlight by clouds","fil":"Pagsipsip ng mga ulap sa lahat ng sikat ng araw","correct":false},{"en":"Air pressure pushing colors apart","fil":"Paghihiwalay ng mga kulay dahil sa presyon ng hangin","correct":false}]$$),
 ($$starter-weather-snow$$,
  $$What must happen in a cold cloud for snow to form?$$,
  $$Ano ang kailangang mangyari sa malamig na ulap upang mabuo ang niyebe?$$,
  $$Ice crystals grow in cold clouds and then fall to the ground as snow.$$ ,
  $$Lumalaki ang mga kristal ng yelo sa malamig na ulap at bumabagsak sa lupa bilang niyebe.$$ ,
  $$[{"en":"Ice crystals grow and fall from the cloud","fil":"Lumalaki at bumabagsak ang mga kristal ng yelo mula sa ulap","correct":true},{"en":"Warm raindrops evaporate before reaching the ground","fil":"Sumisingaw ang maiinit na patak bago makarating sa lupa","correct":false},{"en":"Water vapor changes into fog at ground level","fil":"Nagiging hamog sa lupa ang singaw ng tubig","correct":false},{"en":"Wind compresses air into liquid water","fil":"Pinipiga ng hangin ang hangin hanggang maging likidong tubig","correct":false}]$$),
 ($$starter-weather-temperature$$,
  $$A thermometer shows that the air has warmed. Which property has changed?$$,
  $$Ipinapakita ng thermometer na uminit ang hangin. Aling katangian ang nagbago?$$,
  $$Temperature measures how hot or cold the air or another material is.$$ ,
  $$Sinusukat ng temperatura kung gaano kainit o kalamig ang hangin o ibang materyal.$$ ,
  $$[{"en":"Temperature","fil":"Temperatura","correct":true},{"en":"Humidity","fil":"Humidity","correct":false},{"en":"Air pressure","fil":"Presyon ng hangin","correct":false},{"en":"Wind direction only","fil":"Direksiyon lamang ng hangin","correct":false}]$$),
 ($$starter-weather-hurricane$$,
  $$A tropical cyclone develops over a warm tropical ocean. What helps provide its energy?$$,
  $$Nabubuo ang tropical cyclone sa mainit na karagatang tropikal. Ano ang tumutulong magbigay rito ng enerhiya?$$,
  $$Tropical cyclones form over warm tropical oceans and draw energy from the ocean and atmosphere.$$ ,
  $$Nabubuo ang tropical cyclone sa mainit na karagatang tropikal at kumukuha ng enerhiya mula sa karagatan at atmospera.$$ ,
  $$[{"en":"The warm ocean and atmosphere","fil":"Ang mainit na karagatan at atmospera","correct":true},{"en":"Cold land far from the ocean","fil":"Malamig na lupain na malayo sa karagatan","correct":false},{"en":"Light reflected by the Moon","fil":"Liwanag na sinasalamin ng Buwan","correct":false},{"en":"Underground air pockets","fil":"Mga bulsa ng hangin sa ilalim ng lupa","correct":false}]$$),
 ($$starter-weather-water-vapor$$,
  $$A scientist describes water in its gaseous, invisible state. What is it called?$$,
  $$Inilalarawan ng isang siyentista ang tubig sa anyong gas na hindi nakikita. Ano ang tawag dito?$$,
  $$Water vapor is water in its gaseous state and cannot be seen with the unaided eye.$$ ,
  $$Ang singaw ng tubig ay tubig sa anyong gas at hindi nakikita ng mata lamang.$$ ,
  $$[{"en":"Water vapor","fil":"Singaw ng tubig","correct":true},{"en":"Cloud droplets","fil":"Mga patak ng ulap","correct":false},{"en":"Hail","fil":"Hail","correct":false},{"en":"Snow crystals","fil":"Mga kristal ng niyebe","correct":false}]$$),
 ($$starter-weather-definition$$,
  $$A report says it is windy and cool in one city this morning. What does that report describe?$$,
  $$Sinasabi ng ulat na mahangin at malamig sa isang lungsod ngayong umaga. Ano ang inilalarawan nito?$$,
  $$Weather is the condition of the atmosphere at a particular time and place.$$ ,
  $$Ang panahon ay kalagayan ng atmospera sa isang tiyak na oras at lugar.$$ ,
  $$[{"en":"The weather at that place and time","fil":"Lagay ng panahon sa lugar at oras na iyon","correct":true},{"en":"The climate over many decades","fil":"Klima sa loob ng maraming dekada","correct":false},{"en":"The usual weather of the whole planet","fil":"Karaniwang panahon sa buong mundo","correct":false},{"en":"The amount of water stored underground","fil":"Dami ng tubig na nakaimbak sa ilalim ng lupa","correct":false}]$$),
 ($$starter-weather-wind$$,
  $$Leaves move as air travels across a field. What is this moving air called?$$,
  $$Gumagalaw ang mga dahon habang dumadaloy ang hangin sa bukid. Ano ang tawag sa gumagalaw na hanging ito?$$,
  $$Wind is air moving from one place to another.$$ ,
  $$Ang hangin ay hanging gumagalaw mula sa isang lugar patungo sa iba.$$ ,
  $$[{"en":"Wind","fil":"Hangin","correct":true},{"en":"Humidity","fil":"Humidity","correct":false},{"en":"A cloud droplet","fil":"Patak ng ulap","correct":false},{"en":"Air temperature","fil":"Temperatura ng hangin","correct":false}]$$)
) AS v(content_key,quiz_en,quiz_fil,explanation_en,explanation_fil,options)
WHERE c.content_key=v.content_key;
